// Generated by TIA from the code of web-portal (commit 906a013d5a73) on 2026-11-25: /login -> /done.
// Review before use: values come from the input rules found in the code; TODO marks what the code does not say.
const { test, expect } = require('@playwright/test');

const BASE_URL = process.env.BASE_URL || "http://localhost:3000";

test("flow /login to /done", async ({ page }) => {
  // ---- screen /login (Login) ----
  await page.goto(BASE_URL + "/login");
  await page.locator('#username').fill("aaa");
  await page.locator('#password').fill("aaaaaaaa");
  await page.getByTestId('sign-in').click();

  // ---- screen /accounts (Accounts) ----
  await expect(page).toHaveURL(new RegExp("/accounts$"));
  await page.locator('#account').selectOption("ACC1001");
  await page.getByTestId('make-payment').click();

  // ---- screen /pay (Pay) ----
  await expect(page).toHaveURL(new RegExp("/pay$"));
  await page.locator('#amount').fill("0.01");
  await page.locator('#currency').selectOption("EUR");
  await page.locator('#reference').fill("aaaaaaaaaaaaaaaaaa");
  const [response] = await Promise.all([
    page.waitForResponse(r => r.request().method() === "POST" && new RegExp("^/payments$").test(new URL(r.url()).pathname)),
    page.getByTestId('pay').click(),
  ]);
  expect(response.status()).toBe(201);

  // ---- screen /done (Done) ----
  await expect(page).toHaveURL(new RegExp("/done$"));
});

